import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import java.util.zip.*;import java.util.*;
public class NativeFarChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static ClassNode cls(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}
 static boolean call(ClassNode c,String method,String owner,String name){for(MethodNode m:c.methods)if(method==null||m.name.equals(method))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode x&&x.owner.equals(owner)&&x.name.equals(name))return true;return false;}
 public static void main(String[]args)throws Exception{try(ZipFile z=new ZipFile(args[0])){String audio="dev/zomboid/tacz/Audio";ClassNode manager=cls(z,"com/tacz/guns/sound/SoundManager");ok(call(manager,"sendSoundToNearby",audio,"range"),"server packet radius uses patched common range");ok(call(manager,"sendSoundToNearby",audio,"listeners"),"server sends through positional listener expansion");ok(call(manager,"sendSoundToNearby",audio,"positioned"),"packet includes source coordinates");ok(call(cls(z,audio),"listeners","dev/zomboid/tacz/R","call"),"existing global same-world player lookup retained");ClassNode remote=cls(z,"dev/zomboid/tacz/RemoteAudio");boolean proxy=false,distance=false,track=false;for(MethodNode m:remote.methods)for(AbstractInsnNode i:m.instructions)if(i instanceof LdcInsnNode x){proxy|="net.minecraft.world.entity.decoration.ArmorStand".equals(x.cst);distance|="getDistance".equals(x.cst);track|="getEntity".equals(x.cst);}ok(proxy&&distance&&track,"untracked shooter positional playback and packet distance already supported");ClassNode play=cls(z,"com/tacz/guns/client/sound/SoundPlayManager");ok(call(play,"playShootSound",audio,"range")&&call(play,"playSilenceSound",audio,"range"),"local normal and suppressed shots use same range hook");ok(call(play,"playMessageSound","dev/zomboid/tacz/RemoteAudio","play"),"received packet invokes untracked-source playback");}System.out.println("NATIVE_DISTANCE_PATH_CHECKS="+checks);}}
